// Blank is a new, empty document as a file.
func Blank() ([]byte, error) {
	p := opc.NewPackage()
	p.Put("word/document.xml", ctMain, []byte(blankDocument))
	p.Put("word/styles.xml", ctStyles, []byte(blankStyles))
	p.Put("word/settings.xml", ctSettings, []byte(blankSettings))
	p.Put("word/theme/theme1.xml", ctTheme, []byte(blankTheme))
	p.Put("docProps/core.xml", ctCore, []byte(blankCore))
	p.Put("docProps/app.xml", ctApp, []byte(blankApp))
	p.AddRel("", opc.RelOfficeDocument, "word/document.xml", false)
	p.AddRel("", opc.RelCoreProps, "docProps/core.xml", false)
	p.AddRel("", opc.RelAppProps, "docProps/app.xml", false)
	p.AddRel("word/document.xml", relStyles, "styles.xml", false)
	p.AddRel("word/document.xml", relSettings, "settings.xml", false)
	p.AddRel("word/document.xml", relTheme, "theme/theme1.xml", false)
	return p.Bytes()
}
